// ***************
// Filename: watchdog_top.sv
// Author: FPGA Cores 4 U
// Description: watchdog with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map watchdog_regs
//   (u_regs, src/include/watchdog_regs.sv, ID "WDOG", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic watchdog (u_core,
//   src/watchdog.sv), joined by the register interface watchdog_regs_if
//   (u_regs_if). Generated by ip/scripts/regmap_gen.py from
//   watchdog_regs.json and the ports of watchdog: regenerate after changing
//   either. Clock - aclk. Reset - synchronous active low aresetn.
// Date: 2026-10-16
module watchdog_top #(
  parameter int RESET_CYCLES = 16
) (
  input  logic aclk,
  input  logic aresetn,
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  output logic irq_o,
  output logic wdt_reset_o
);
  // register interface between the register map and the logic
  watchdog_regs_if u_regs_if ();

  watchdog_regs u_regs (
    .aclk,
    .aresetn,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  watchdog #(
    .RESET_CYCLES(RESET_CYCLES)
  ) u_core (
    .aclk,
    .aresetn,
    .irq_o,
    .wdt_reset_o,
    .regs(u_regs_if)
  );
endmodule
